  "inlineSchema": "// generator client {\n//   provider        = \"prisma-client-js\"\n//   binaryTargets = [\"native\"]  // Add this line\n// }\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"app/generated/prisma/client\"\n  binaryTargets = [\"native\", \"debian-openssl-1.1.x\"] // include your server's runtime\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id           String      @id @default(uuid())\n  firstName    String\n  lastName     String\n  email        String      @unique\n  password     String\n  roleId       String      @map(\"role_id\")\n  role         Role        @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  restaurant   Restaurant? @relation(fields: [restaurantId], references: [id], onDelete: Cascade)\n  restaurantId String?     @map(\"restaurant_id\")\n  createdAt    DateTime    @default(now()) @map(\"created_at\")\n  updatedAt    DateTime    @updatedAt @map(\"updated_at\")\n  socketId     String? // Add this line\n}\n\nmodel Role {\n  id              String           @id @default(uuid())\n  name            String\n  users           User[]\n  permissions     Permission[]\n  rolePermissions RolePermission[]\n  createdAt       DateTime         @default(now()) @map(\"created_at\")\n  updatedAt       DateTime         @updatedAt @map(\"updated_at\")\n}\n\nmodel Permission {\n  id              String           @id @default(uuid())\n  name            String\n  roles           Role[]\n  rolePermissions RolePermission[]\n}\n\nmodel RolePermission {\n  id           String @id @default(uuid())\n  roleId       String @map(\"role_id\")\n  permissionId String @map(\"permission_id\")\n\n  role       Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@unique([roleId, permissionId])\n}\n\n// New Models\n\nmodel Restaurant {\n  id           String           @id @default(uuid())\n  name         String\n  phone        String?\n  address      String?\n  logo         String?\n  qrCodeImage  String? // Base64 or URL of the QR code image\n  subscription SubscriptionType @default(BASIC)\n  isOpen       Boolean          @default(true)\n  isActive     Boolean          @default(true)\n  menuItems    MenuItem[]\n  categories   Category[]\n  orders       Order[]\n  tables       Table[]\n  users        User[]\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n}\n\nmodel MenuItem {\n  id           String          @id @default(uuid())\n  name         String\n  price        Float\n  ingredients  String?\n  image        String?\n  restaurant   Restaurant      @relation(fields: [restaurantId], references: [id], onDelete: Cascade)\n  restaurantId String          @map(\"restaurant_id\")\n  category     Category        @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  categoryId   String          @map(\"category_id\")\n  orderItems   OrderItem[]\n  status       MenuItemStatus  @default(AVAILABLE)\n  destination  DestinationType @default(KITCHEN) // Specify where to send the item\n  createdAt    DateTime        @default(now()) @map(\"created_at\")\n  updatedAt    DateTime        @updatedAt @map(\"updated_at\")\n}\n\nmodel Order {\n  id            String         @id @default(uuid())\n  status        OrderStatus\n  items         OrderItem[]\n  number        Int?\n  restaurant    Restaurant     @relation(fields: [restaurantId], references: [id], onDelete: Cascade)\n  restaurantId  String         @map(\"restaurant_id\")\n  bills         Bill[] // Changed to one-to-many relationship\n  kitchenOrders KitchenOrder[]\n  barOrders     BarOrder[] // Added BarOrders relation\n  table         Table?         @relation(fields: [tableId], references: [id], onDelete: Cascade) // Relation to Table\n  tableId       String?        @map(\"table_id\")\n  createdAt     DateTime       @default(now()) @map(\"created_at\")\n  updatedAt     DateTime       @updatedAt @map(\"updated_at\")\n}\n\nmodel OrderItem {\n  id                  String   @id @default(uuid())\n  quantity            Int\n  menuItem            MenuItem @relation(fields: [menuItemId], references: [id], onDelete: Cascade)\n  menuItemId          String   @map(\"menu_item_id\")\n  specialInstructions String?\n  order               Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  orderId             String   @map(\"order_id\")\n  createdAt           DateTime @default(now()) @map(\"created_at\")\n  updatedAt           DateTime @updatedAt @map(\"updated_at\")\n}\n\nmodel Bill {\n  id                String   @id @default(uuid())\n  total             Float\n  order             Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  orderId           String   @map(\"order_id\")\n  cashPaymentAmount Float?\n  provider          String?\n  transferAmount    Float?\n  createdAt         DateTime @default(now()) @map(\"created_at\")\n  updatedAt         DateTime @updatedAt @map(\"updated_at\")\n}\n\nmodel KitchenOrder {\n  id        String      @id @default(uuid())\n  order     Order       @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  orderId   String      @map(\"order_id\")\n  status    OrderStatus\n  createdAt DateTime    @default(now()) @map(\"created_at\")\n  updatedAt DateTime    @updatedAt @map(\"updated_at\")\n}\n\nmodel BarOrder {\n  id        String      @id @default(uuid())\n  status    OrderStatus\n  createdAt DateTime    @default(now()) @map(\"created_at\")\n  updatedAt DateTime    @updatedAt @map(\"updated_at\")\n\n  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  orderId String @map(\"order_id\")\n}\n\nmodel Table {\n  id           String      @id @default(uuid())\n  number       String // Unique identifier for the table, like \"Table 1\"\n  restaurant   Restaurant  @relation(fields: [restaurantId], references: [id], onDelete: Cascade)\n  restaurantId String      @map(\"restaurant_id\")\n  qrCodeImage  String // Base64 or URL of the QR code image\n  orders       Order[] // One-to-many relation to orders\n  status       TableStatus @default(AVAILABLE) // Status of the table\n  createdAt    DateTime    @default(now()) @map(\"created_at\")\n  updatedAt    DateTime    @updatedAt @map(\"updated_at\")\n}\n\n// Updated Category Model (No direct association with Restaurant)\nmodel Category {\n  id           String      @id @default(uuid())\n  name         String\n  restaurant   Restaurant? @relation(fields: [restaurantId], references: [id], onDelete: Cascade)\n  restaurantId String?     @map(\"restaurant_id\")\n  menuItems    MenuItem[]\n  createdAt    DateTime    @default(now()) @map(\"created_at\")\n  updatedAt    DateTime    @updatedAt @map(\"updated_at\")\n}\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  message   String\n  type      String\n  status    String   @default(\"unread\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Consolidated OrderStatus Enum\nenum OrderStatus {\n  PENDING\n  IN_PROGRESS\n  READY\n  SERVED\n  CANCELLED\n  PAID\n  PAYMENT_REQUESTED\n}\n\nenum TableStatus {\n  AVAILABLE\n  OCCUPIED\n  RESERVED\n}\n\nenum DestinationType {\n  KITCHEN\n  BAR\n}\n\nenum MenuItemStatus {\n  AVAILABLE\n  SOLD_OUT\n}\n\nenum SubscriptionType {\n  BASIC\n  STANDARD\n  PREMIUM\n}\n",
